// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { facetModel } from "../../../main/frontend/graph-explorer/graph-facets.ts";
import { fitBoxes } from "../../../main/frontend/graph-explorer/graph-geometry.ts";
import { mapFrame } from "../../../main/frontend/graph-explorer/graph-literals.ts";
import { newEdgesOf } from "../../../main/frontend/graph-explorer/graph-operations.ts";
import { boxBounds, revealBoxesIncrementally } from "../../../main/frontend/graph-explorer/graph-viewport.ts";

// Spreading this many arguments (Math.max(...values)) overflows the call stack in V8; JavaScriptCore already fails
// above 65,536. Every bound below must come from a loop or a reduction instead.
const BEYOND_SPREAD_LIMIT = 200_000;

const XSD_INTEGER = "http://www.w3.org/2001/XMLSchema#integer";

test("a range facet over more numeric values than a spread can take finds its bounds", () => {
  const nodes = [];
  const literals = [];
  const edges = [];
  for (let index = 0; index < BEYOND_SPREAD_LIMIT; index++) {
    const source = `urn:item:${index}`;
    const value = index === 7 ? -5 : index === 11 ? 1_000_001 : index % 1000;
    const literal = { id: `"${index}-${value}"`, label: String(value), termValue: String(value), kind: "literal", datatype: XSD_INTEGER };
    nodes.push({ id: source, label: source, kind: "iri" });
    literals.push(literal);
    edges.push({ id: `e${index}`, source, predicate: "urn:size", label: "size", target: literal.id });
  }
  const model = facetModel({
    nodes,
    edges,
    nodeById: new Map([...nodes, ...literals].map((node) => [node.id, node])),
    selection: new Map(),
    typesOf: () => [],
    hiddenPredicates: new Set(),
  });
  const size = model.facets.find((facet) => facet.id === "urn:size");

  assert.equal(size.range.kind, "number");
  assert.equal(size.range.min, -5);
  assert.equal(size.range.max, 1_000_001);
  assert.equal(size.range.values.length, BEYOND_SPREAD_LIMIT);
});

function boxes(count, extreme) {
  const result = [];
  for (let index = 0; index < count; index++) {
    result.push({ x: (index % 500) * 10, y: Math.floor(index / 500) * 10, width: 20, height: 10 });
  }
  result[count - 1] = extreme;
  return result;
}

test("box bounds cover every box of a graph larger than a spread can take", () => {
  const many = boxes(BEYOND_SPREAD_LIMIT, { x: -10_000, y: 50_000, width: 100, height: 40 });

  const bounds = boxBounds(many);

  assert.equal(bounds.minX, -10_050);
  assert.equal(bounds.maxX, 499 * 10 + 10);
  assert.equal(bounds.minY, -5);
  assert.equal(bounds.maxY, 50_020);
});

test("box bounds of a single box, and of none, are well defined", () => {
  assert.deepEqual(boxBounds([{ x: 1, y: 2, width: 4, height: 6 }]), { minX: -1, maxX: 3, minY: -1, maxY: 5 });
  assert.deepEqual(boxBounds([]), { minX: Infinity, maxX: -Infinity, minY: Infinity, maxY: -Infinity });
  assert.deepEqual(fitBoxes([]), { x: 0, y: 0, k: 1 }, "Fit of nothing keeps the identity transform");
});

test("Fit and the incremental reveal handle more boxes than a spread can take", () => {
  const many = boxes(BEYOND_SPREAD_LIMIT, { x: 40_000, y: 40_000, width: 280, height: 46 });
  const fit = fitBoxes(many);
  for (const value of [fit.x, fit.y, fit.k]) assert.ok(Number.isFinite(value));
  const far = many.at(-1);
  assert.ok((far.x + far.width / 2) * fit.k + fit.x <= 1280 + 1e-6, "the farthest box is inside the fitted view");

  const current = { x: 0, y: 0, k: 1 };
  const revealed = revealBoxesIncrementally(current, { x: 0, y: 0 }, { x: 0, y: 0 }, many);
  for (const value of [revealed.x, revealed.y, revealed.k]) assert.ok(Number.isFinite(value));
  assert.ok(revealed.k <= current.k, "revealing never zooms in");
});

test("a map frame around more places than a spread can take", () => {
  const places = [];
  for (let index = 0; index < BEYOND_SPREAD_LIMIT; index++) {
    places.push({ latitude: 10 + (index % 100) / 1000, longitude: 20 + (index % 50) / 1000 });
  }
  places[3] = { latitude: -60, longitude: -170 };

  const frame = mapFrame(places);

  assert.ok(frame.south <= -60 && frame.west <= -170);
  assert.ok(frame.north >= 10.099 && frame.east >= 20.049);
});

test("the new edges of a merge come from one pass over each graph", () => {
  const edge = (id) => ({ id, source: "urn:s", predicate: "urn:p", label: "p", target: id });
  const before = { edges: [] };
  for (let index = 0; index < BEYOND_SPREAD_LIMIT; index++) before.edges.push(edge(`old-${index}`));
  const added = [edge("new-b"), edge("new-a"), edge("new-c")];
  const after = { edges: [...before.edges.slice(0, 1000), added[0], ...before.edges.slice(1000), added[1], added[2]] };

  const started = performance.now();
  const found = newEdgesOf(before, after);
  const elapsed = performance.now() - started;

  assert.deepEqual(found.map((item) => item.id), ["new-b", "new-a", "new-c"], "in the merged graph's order");
  assert.ok(elapsed < 2000, `a linear diff of ${BEYOND_SPREAD_LIMIT} edges took ${elapsed.toFixed(0)} ms`);
});

test("the edge diff compares identities, not objects, and finds nothing new in an unchanged graph", () => {
  const before = { edges: [{ id: "a" }, { id: "b" }] };
  assert.deepEqual(newEdgesOf(before, { edges: [{ id: "a" }, { id: "b" }] }), [], "copies of known edges");
  assert.deepEqual(newEdgesOf(before, { edges: [] }), [], "a graph that lost edges adds none");
  assert.deepEqual(newEdgesOf({ edges: [] }, before).map((item) => item.id), ["a", "b"], "everything is new");
});
